import type { SessionSummary } from './types';

function haystack(s: SessionSummary): string {
  return [
    s.id,
    s.file,
    s.started_at ?? '',
    s.source_lang,
    s.target_lang,
    s.stt_provider,
    s.model ?? '',
    ...Object.values(s.speakers),
  ]
    .join('\n')
    .toLowerCase();
}

export function sessionMatches(s: SessionSummary, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (q === '') return true;
  return haystack(s).includes(q);
}

export function filterSessions(
  sessions: SessionSummary[],
  query: string,
): SessionSummary[] {
  return sessions.filter((s) => sessionMatches(s, query));
}

